export const QUESTION_MAP: Record<string, MCQ> = QUESTIONS.reduce((acc, q) => {
  acc[q.id] = q;
  return acc;
}, {} as Record<string, MCQ>);

export const getQuestionsByCollegeAndSubject = (
  collegeId: string,
  subjectId: string
): MCQ[] => {
  return QUESTIONS.filter(
    (q) => q.collegeId === collegeId && q.subjectId === subjectId
  ).sort((a, b) => a.originalQuestionNumber - b.originalQuestionNumber);
};

export const getQuestionsByCollege = (collegeId: string): MCQ[] => {
  return QUESTIONS.filter((q) => q.collegeId === collegeId);
};

export const searchQuestions = (query: string): MCQ[] => {
  if (!query || query.trim().length === 0) return [];
  const qClean = query.toLowerCase().trim();
  return QUESTIONS.filter((q) => {
    return (
      q.question.toLowerCase().includes(qClean) ||
      q.collegeName.toLowerCase().includes(qClean) ||
      q.subjectName.toLowerCase().includes(qClean) ||
      q.options.some((o) => o.text.toLowerCase().includes(qClean)) ||
      q.explanation.toLowerCase().includes(qClean)
    );
  });
};
